<script>
(function(){
  var ids=['dp1-bc','dp1-imgcol','dp1-info'];
  function trigger(){ids.forEach(function(id){var el=document.getElementById(id);if(el)el.classList.add('dp1-vis');});}
  if(document.readyState==='complete'){trigger();}else{window.addEventListener('load',trigger);}
  var mainImg=document.getElementById('dp1-main-img');
  var thumbs=document.querySelectorAll('.dp1-hero__thumb');
  thumbs.forEach(function(thumb){
    thumb.addEventListener('click',function(){
      var src=thumb.getAttribute('data-src');
      if(src&&mainImg){mainImg.style.opacity='0';mainImg.style.transition='opacity .2s ease';setTimeout(function(){mainImg.src=src;mainImg.style.opacity='1';},180);}
      thumbs.forEach(function(t){t.classList.remove('dp1-hero__thumb--active');});
      thumb.classList.add('dp1-hero__thumb--active');
    });
  });
